import numpy as np
import pytest
from sampling import next_token_probs, sample

LOGITS = [4.0, 3.0, 2.0, 1.0, 0.0]


def test_probs_sum_to_one():
    for kw in [{}, {"temperature": 0.5}, {"top_k": 2}, {"top_p": 0.8}]:
        assert next_token_probs(LOGITS, **kw).sum() == pytest.approx(1.0)


def test_zero_temperature_is_greedy():
    p = next_token_probs(LOGITS, temperature=0)
    assert p.argmax() == 0 and p[0] == 1.0


def test_low_temperature_sharpens_high_flattens():
    base = next_token_probs(LOGITS, temperature=1.0)
    assert next_token_probs(LOGITS, temperature=0.3)[0] > base[0]
    assert next_token_probs(LOGITS, temperature=3.0)[0] < base[0]


def test_top_k_zeroes_the_tail():
    p = next_token_probs(LOGITS, top_k=2)
    assert (p[2:] == 0).all() and (p[:2] > 0).all()


def test_top_p_keeps_smallest_nucleus():
    base = next_token_probs(LOGITS)            # about [0.64, 0.23, 0.09, 0.03, 0.01]
    p = next_token_probs(LOGITS, top_p=0.8)    # 0.64 < 0.8 so token 1 is also needed
    assert (p > 0).sum() == 2
    assert p[0] == pytest.approx(base[0] / (base[0] + base[1]))


def test_top_p_tiny_still_keeps_one_token():
    assert (next_token_probs(LOGITS, top_p=0.01) > 0).sum() == 1


def test_filtered_tokens_are_never_sampled():
    rng = np.random.default_rng(0)
    draws = {sample(LOGITS, rng, top_k=2) for _ in range(500)}
    assert draws <= {0, 1}

import json

# A scripted "model": first it asks for a tool, then it answers using the tool result.
SCRIPT = [
    {"role": "assistant", "tool_calls": [{"id": "call_1", "name": "get_order_status",
                                          "arguments": '{"order_id": "A-17"}'}]},
    {"role": "assistant", "content": "Order A-17 has shipped."},
]


def fake_model(messages):
    return SCRIPT[sum(1 for m in messages if m["role"] == "assistant")]


TOOLS = {"get_order_status": lambda order_id: {"order_id": order_id, "status": "shipped"}}


def run(user_text, max_steps=5):
    messages = [{"role": "user", "content": user_text}]
    for _ in range(max_steps):                       # hard cap: a loop must always terminate
        reply = fake_model(messages)
        messages.append(reply)
        if "tool_calls" not in reply:
            return reply["content"], messages
        for call in reply["tool_calls"]:
            try:
                args = json.loads(call["arguments"])           # model output is untrusted: parse safely
                result = TOOLS[call["name"]](**args)           # only allow-listed tools
            except (KeyError, TypeError, ValueError) as exc:
                result = {"error": f"bad tool call: {type(exc).__name__}"}
            messages.append({"role": "tool", "tool_call_id": call["id"], "content": json.dumps(result)})
    raise RuntimeError("tool loop did not finish")


if __name__ == "__main__":
    answer, transcript = run("Where is order A-17?")
    print(answer)
    print([m["role"] for m in transcript])      # user, assistant, tool, assistant

import json


def parse_sse(lines):
    """Yield the data payload of each server-sent event. Events end with a blank line."""
    data = []
    for line in lines:
        line = line.rstrip("\n")
        if line == "":
            if data:
                yield "\n".join(data)
                data = []
        elif line.startswith("data:"):
            data.append(line[5:].lstrip())
    if data:
        yield "\n".join(data)


def accumulate(lines):
    """Join text deltas; stop at the [DONE] sentinel used by some providers."""
    text = []
    for payload in parse_sse(lines):
        if payload == "[DONE]":
            break
        text.append(json.loads(payload)["delta"])
        yield "".join(text)                      # the partial text so far, e.g. for the UI


def try_parse_partial_json(text):
    """Return the object if the buffer is already complete JSON, else None. Never trust half a object."""
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return None


if __name__ == "__main__":
    raw = ['data: {"delta": "{\\"a\\": "}\n', "\n", 'data: {"delta": "1}"}\n', "\n", "data: [DONE]\n", "\n"]
    for partial in accumulate(raw):
        print(repr(partial), "->", try_parse_partial_json(partial))
